With more than a decade of experience in the industry, the agent has built up local knowledge of the northern Pretoria and Mamelodi property markets specifically, an area not every Pretoria-wide agency focuses on. Masilo Nkwe operates from Heatherview Hills in Heatherdale, Akasia, serving buyers and sellers across the northern Pretoria and Mamelodi suburbs.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://benebael.co.za/', '$[#]', 'https://masilo-nkwe.business.site/'), description_enriched_at = datetime('now') WHERE slug = 'masilo-nkwe-heatherdale' AND description = 'Masilo Nkwe is a real estate agent affiliated with eXp South Africa, specialising in new developments and residential property sales across Soshanguve, Rosslyn, Klerksoord, Pretoria North, Lotus Gardens and Mamelodi, with more than a decade of experience in the industry.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
